<script setup>
import { reactive, computed, ref } from 'vue'
import Icon from './Icon.vue'
import { clone, today, categories, money, balance } from '../utils'
const props=defineProps({ transaction:Object, defaults:Object, orders:Array, busy:Boolean, error:String })
const emit=defineEmits(['save','cancel','delete'])
const form=reactive(props.transaction?clone(props.transaction):{date:today(),category:'采购-布料',title:'',amount:'',orderId:'',note:'',...props.defaults})
const isIncome=computed(()=>form.category.startsWith('收入-')||form.category==='其他收入')
const localError=ref('')
function selectedOrder(){const order=props.orders.find(o=>o.id===form.orderId);if(order&&!form.title)form.title=order.customer+' · '+order.style}
function submit(){localError.value='';if(!Number.isFinite(Number(form.amount))||Number(form.amount)<=0){localError.value='请填写大于 0 的实际发生金额。';return}emit('save',{date:form.date,category:form.category,title:form.title,amount:Number(form.amount),orderId:form.orderId,note:form.note,type:isIncome.value?'income':'expense'})}
</script>
<template><form id="transaction-form" @submit.prevent="submit"><div class="dialog-body"><div class="form-grid"><label class="field">发生日期 *<input name="date" type="date" v-model="form.date" required></label><label class="field">收支类型 *<select name="category" v-model="form.category"><option v-for="c in categories" :key="c">{{c}}</option></select></label><label class="field full">对应订单（可选）<select name="orderId" v-model="form.orderId" @change="selectedOrder"><option value="">不关联订单</option><option v-for="o in orders" :key="o.id" :value="o.id">{{o.id}} · {{o.customer}} · 待收 ¥{{money(balance(o))}}</option></select></label><label class="field full">物品 / 事项说明 *<input name="title" v-model="form.title" maxlength="200" placeholder="运费可写：第 2 周，共 8 个包裹" required></label><label class="field">支出金额（元）<input name="expense" type="number" :value="!isIncome?form.amount:''" :disabled="isIncome" :required="!isIncome" @input="form.amount=$event.target.value" min="0.01" max="9999999" step="0.01" inputmode="decimal"></label><label class="field">收入金额（元）<input name="income" type="number" :value="isIncome?form.amount:''" :disabled="!isIncome" :required="isIncome" @input="form.amount=$event.target.value" min="0.01" max="9999999" step="0.01" inputmode="decimal"></label><label class="field full">备注<textarea name="note" v-model="form.note" rows="3" maxlength="2000" placeholder="数量、用途，退款或金额更正原因等"></textarea></label></div><p class="form-note">{{isIncome?'填写实际到账的钱。关联订单后，会自动更新定金或尾款；不要重复登记已经存在的收款。':'填写真实花掉的钱。运费可按周合并，注明周次与包裹数量。工具一次计入采购成本。'}}</p><button v-if="transaction" type="button" class="btn danger-text" @click="emit('delete')">删除这笔流水</button><p v-if="error||localError" class="inline-error" role="alert">{{error||localError}}</p></div><div class="dialog-footer"><button type="button" class="btn" :disabled="busy" @click="emit('cancel')">取消</button><button class="btn btn-primary" type="submit" :disabled="busy"><Icon name="check" />{{busy?'正在保存…':'保存收支'}}</button></div></form></template>
